    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        if not events:
            return 0

        # Initialize with the first button's time
        max_time = events[0][1]
        result_index = events[0][0]

        # Iterate through remaining events to find the longest duration
        for i in range(1, len(events)):
            time_diff = events[i][1] - events[i-1][1]
            if time_diff > max_time:
                max_time = time_diff
                result_index = events[i][0]
            elif time_diff == max_time:
                # If there's a tie, choose the button with the smallest index
                result_index = min(result_index, events[i][0])

        return result_index

