class Solution:
    def maxLength(self, nums: List[int]) -> int:
        n = len(nums)
        max_len = 1

        for i in range(n):
            current_gcd = nums[i]
            current_lcm = nums[i]
            current_prod = nums[i]

            if current_prod == current_lcm * current_gcd:
                max_len = max(max_len, 1)

            for j in range(i + 1, n):
                current_gcd = math.gcd(current_gcd, nums[j])
                g = math.gcd(current_lcm, nums[j])
                current_lcm = (current_lcm * nums[j]) // g
                current_prod = current_prod * nums[j]

                if current_prod == current_lcm * current_gcd:
                    max_len = max(max_len, j - i + 1)

        return max_len
